import mongoose from "mongoose";

export async function connectDB() {
  const mongoUri = process.env.MONGO_URI || "mongodb://127.0.0.1:27017/algoyantra";

  if (!mongoUri) {
    throw new Error("MONGO_URI is missing. Add it to server/.env before starting the API.");
  }

  mongoose.set("strictQuery", true);
  try {
    await mongoose.connect(mongoUri);
  } catch (error) {
    throw new Error(
      `MongoDB connection failed for ${mongoUri}. ${
        error.message || "Check whether MongoDB is running and the URI is correct."
      }`,
    );
  }

  // eslint-disable-next-line no-console
  console.log("MongoDB connected successfully.");
}
